<?php
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$labels=['pending'=>'Prêt à transférer','needs_fees'=>'Frais à renseigner','submitted'=>'Réponse incomplète · crédit à vérifier','unknown'=>'Résultat incertain · à vérifier','confirmed'=>'Crédit payout confirmé'];
$canWrite=\App\Services\Auth::can('finance.withdraw');$csrf=$esc($_SESSION['csrf']??'');
?>
<?php foreach($rows as $row): $remaining=$row['rental_id']?\App\Services\DepositWallet::remaining($row):['paid'=>false]; ?><tr data-wallet-id="<?= (int)$row['id'] ?>" data-wallet-rental="<?= (int)$row['rental_id'] ?>"><td><?= $row['reference']?'<a href="/admin/rentals/detail?reference='.rawurlencode($row['reference']).'">'.$esc($row['reference']).'</a>':'Essai #'.(int)$row['id'] ?><br><?= $esc($row['serial']??'') ?><br><small><?= $esc($row['created_at']) ?> UTC</small></td><td><?= $esc($row['customer_name']??'') ?><br><?= $esc($row['customer_phone']??'') ?><br><?= $esc($row['payout_channel']??'') ?></td><td data-wallet-remaining><?php if($remaining['paid']): ?>Payée : <?= (int)$remaining['deposit'] ?> FCFA<br>Retenue : <?= (int)$remaining['deduction'] ?> FCFA<br><strong>À restituer : <?= (int)$remaining['refund'] ?> FCFA</strong><?php else: ?>—<?php endif; ?></td><td><?= (int)$row['amount'] ?> FCFA<br>Dont frais réservés : <?= (int)$row['fee_reserve'] ?> FCFA<br><small>Le reliquat reste dans le solde payout.</small></td><td><?= $esc($labels[$row['status']]??$row['status']) ?><br><?php if($row['http_status']): ?>HTTP <?= (int)$row['http_status'] ?><?php endif; ?><br><?php if(!empty($row['response_summary']) && \App\Services\Auth::can('payout.view')): ?><details data-wallet-details="summary-<?= (int)$row['id'] ?>"><summary>Réponse du transfert</summary><pre><?= $esc($row['response_summary']) ?></pre></details><?php endif; ?><?php if(\App\Services\Auth::can('payout.view')): $trace=\App\Services\SystemStorage::read('xpaye-wallet-transfer-'.(int)$row['id'].'.json'); if($trace): ?><details data-wallet-details="trace-<?= (int)$row['id'] ?>"><summary>Endpoint, payload et réponse API</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $esc(json_encode($trace,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)) ?></pre></details><?php endif;endif; ?></td><td><?= $row['refund_status']?$esc(['pending'=>'En attente','processing'=>'En cours','refunded'=>'Restitution confirmée','initiated'=>'Autorisation à vérifier','unknown'=>'À vérifier','failed'=>'Échec'][$row['refund_status']]??$row['refund_status']):'Aucun retour à rembourser' ?><br><?= isset($row['refund_amount'])?(int)$row['refund_amount'].' FCFA':'' ?></td><td><?= $esc($row['confirmation_proof']??'') ?>
<?php if($canWrite && $row['status']==='pending'): ?><form method="post" action="/admin/deposit-wallet"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="send"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="admin-button">Transférer</button></form><?php endif; ?>
<?php if($canWrite && in_array($row['status'],['submitted','unknown'],true)): ?><form method="post" action="/admin/deposit-wallet"><input type="hidden" name="csrf" value="<?= $csrf ?>"><input type="hidden" name="action" value="confirm"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input name="proof" placeholder="Référence du crédit XPaye" minlength="5" maxlength="240" required aria-label="Preuve du crédit"><label><input type="checkbox" name="credit_checked" value="1" required> Crédit exact de <?= (int)$row['amount'] ?> FCFA vérifié</label><button class="admin-button">Rapprocher le crédit</button></form><?php endif; ?></td></tr><?php endforeach; ?>
